import{_ as t,o as s,c as o,ao as n}from"./chunks/framework.ucUddl5u.js";const g=JSON.parse('{"title":"Enrolling a host for cross-frontend access","description":"","frontmatter":{},"headers":[],"relativePath":"guide/enrolling.md","filePath":"guide/enrolling.md","lastUpdated":null}'),a={name:"guide/enrolling.md"};function i(h,e,l,r,d,c){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="Enrolling-a-host-for-cross-frontend-access" tabindex="-1">Enrolling a host for cross-frontend access <a class="header-anchor" href="#Enrolling-a-host-for-cross-frontend-access" aria-label="Permalink to &quot;Enrolling a host for cross-frontend access {#Enrolling-a-host-for-cross-frontend-access}&quot;">​</a></h1><p>A box is <strong>enrolled</strong> when any frontend in the fleet can select its rows, attach to one, and type — without that frontend having an account, a key, or a route to the box. The route is: frontend → its own forwarded port → the <strong>hub</strong>&#39;s socket for that box → one <code>ssh</code> from the hub → <code>sotd stdio-bridge</code> on the box → that box&#39;s daemon. The hub is the only machine that ever ssh&#39;s in; ADR 0048 is the decision, this page is the procedure.</p><p>Everything here is run by an operator, once per box. Nothing in it is automatic, and every step has a check that fails loudly — &quot;it looked right&quot; is not one of them.</p><h2 id="What-the-hub-ends-up-holding" tabindex="-1">What the hub ends up holding <a class="header-anchor" href="#What-the-hub-ends-up-holding" aria-label="Permalink to &quot;What the hub ends up holding {#What-the-hub-ends-up-holding}&quot;">​</a></h2><p><code>sotd topology apply --yes</code>, run on the hub, writes and enables <strong>one listener per enrolled host</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">File (in <code>~/.config/systemd/user/</code>)</th><th style="text-align:right;">What it is</th></tr></thead><tbody><tr><td style="text-align:right;"><code>sot-host-relay-&lt;host&gt;.socket</code></td><td style="text-align:right;">the listener, at the path <code>sotd topology relay-sockets</code> prints; <code>Accept=yes</code>, <code>SocketMode=0600</code></td></tr><tr><td style="text-align:right;"><code>sot-host-relay-&lt;host&gt;@.service</code></td><td style="text-align:right;">one instance per accepted connection: <code>ssh … &lt;host&gt; sotd stdio-bridge --label sot</code>, the connection as its stdin/stdout</td></tr><tr><td style="text-align:right;"><code>sot-host-relay-&lt;host&gt;.socket.d/topology.conf</code></td><td style="text-align:right;"><code>ConditionHost=&lt;hub&gt;</code> — the fleet shares <code>$HOME</code>, so the unit must run on the hub only</td></tr></tbody></table><p>Both unit files are <strong>generated by <code>apply</code> and rewritten on every run</strong>. A hand edit to them is lost; a per-host override belongs in a drop-in beside them (any name but <code>topology.conf</code>, which is apply&#39;s own):</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.config/systemd/user/sot-host-relay-&lt;host&gt;@.service.d/local.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SOT_RELAY_SOTD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/home/&lt;user&gt;/.local/share/sot/bin/sotd   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># not on the ssh PATH</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SOT_RELAY_LABEL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=sot                                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a second daemon on the box</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SOT_RELAY_TARGET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=&lt;ssh alias&gt;                            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># alias ≠ declared host name</span></span></code></pre></div><p>The host sits in the unit&#39;s <strong>name</strong>, not after an <code>@</code>, because a templated socket with <code>Accept=yes</code> hands its service the connection id and not the socket&#39;s instance (systemd issue #19071) — a per-host prefix is the only spelling in which the service knows which box to ssh to.</p><h2 id="The-checklist" tabindex="-1">The checklist <a class="header-anchor" href="#The-checklist" aria-label="Permalink to &quot;The checklist {#The-checklist}&quot;">​</a></h2><p>Each step&#39;s check must pass before the next one is worth doing.</p><ol><li><p><strong>ssh, from the hub, non-interactively.</strong> <code>ssh -o BatchMode=yes &lt;host&gt; sotd --version</code> prints a version. A prompt, a host-key question or a &quot;command not found&quot; here is the whole enrolment failing early: nothing downstream runs attended. If <code>sotd</code> is found interactively but not this way, note its full path for the <code>SOT_RELAY_SOTD</code> override above rather than editing shell profiles.</p></li><li><p><strong><code>sotd</code> runs as a user service on the box</strong>, started by the OS, not by a launcher, surviving with nobody logged in. On the box: <code>systemctl --user is-enabled sotd.service</code> (plus <code>loginctl enable-linger</code> where that applies) and <code>sotd status</code> answers. An instrument box wants this regardless of anything on this page.</p></li><li><p><strong>The bridge answers.</strong> From the hub, pipe one hello frame through <code>ssh -o BatchMode=yes &lt;host&gt; sotd stdio-bridge --label sot</code> and get the daemon&#39;s own reply, byte for byte, with nothing else on stdout. Record the label the box was enrolled with. With the daemon stopped, the same command must exit nonzero <strong>at once</strong>, one line on stderr, nothing on stdout — an honest failure, not a hang.</p></li><li><p><strong>Multiplexing is on.</strong> The generated service already passes <code>-o ControlMaster=auto -o ControlPath=&lt;runtime&gt;/sot-host-relay-ssh-%C -o ControlPersist=600</code>, so no ssh-config change is needed for this alone. Prefer the config file when the host needs its own user, port, key or jump host anyway — put the multiplexing there too and keep one place to look:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ~/.ssh/config on the hub</span></span>
<span class="line"><span>Host &lt;host&gt;</span></span>
<span class="line"><span>    ControlMaster auto</span></span>
<span class="line"><span>    ControlPath ~/.ssh/cm-%C</span></span>
<span class="line"><span>    ControlPersist 10m</span></span></code></pre></div><p>Check, after a frontend has connected: the hub&#39;s journal shows one ssh connection serving several bridge instances, not one connection each (<code>journalctl --user -u &#39;sot-host-relay-&lt;host&gt;@*&#39;</code>).</p></li><li><p><strong>Update ownership is safe to move.</strong> Declaring <code>daemon = true</code> makes the box&#39;s own backend the owner of its updates instead of its frontend&#39;s self-update. Confirm the box&#39;s backend is healthy and at the expected version <em>before</em> step 6, not after.</p></li><li><p><strong>Declare it, one box at a time.</strong> In the hub&#39;s canonical <code>~/.config/sot/hosts.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&lt;host&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">daemon = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # only if it runs a frontend of its own</span></span></code></pre></div><p>Then on the hub: <code>sotd topology apply</code> (a dry run — read it) and <code>sotd topology apply --yes</code>. It must enable exactly one <code>sot-host-relay-&lt;host&gt;.socket</code> and disable nothing you did not expect. On every other box: <code>sotd topology sync</code>.</p></li><li><p><strong>Verify end to end.</strong> On the hub, <code>sotd status</code> reports that box&#39;s real rows through <code>unix:&lt;runtime&gt;/sot-host-&lt;host&gt;.sock</code>. From another machine, relaunch the frontend: the host appears in Hosts mode, its rows in Sessions mode, attaching to one gives a read-write pty, and typing at the box itself takes the pen back.</p></li></ol><h2 id="Reading-a-failure" tabindex="-1">Reading a failure <a class="header-anchor" href="#Reading-a-failure" aria-label="Permalink to &quot;Reading a failure {#Reading-a-failure}&quot;">​</a></h2><ul><li><p><strong>The socket file exists and the box is down.</strong> Expected, and not a contradiction: systemd owns that socket, so it is present whether or not anything is behind it. The frontend renders the host unreachable and greys its last-known rows. Only a completed hello ever means &quot;up&quot;.</p></li><li><p><strong>A frontend logs <code>has no relay socket on hub &#39;&lt;hub&gt;&#39;</code>.</strong> The box is in the plan but the hub has no listener for it — step 6 was not applied on the hub, or apply ran while the box was not yet declared.</p></li><li><p><strong><code>sotd topology apply</code> refuses.</strong> It only runs on the hub, and says so, naming the hub. Run it there.</p></li><li><p><strong>The bridge instance fails per connection.</strong> <code>journalctl --user -u &#39;sot-host-relay-&lt;host&gt;@*&#39;</code> has ssh&#39;s own line: a refused key, an unknown host key, or <code>sotd: command not found</code> (step 1&#39;s check, and the <code>SOT_RELAY_SOTD</code> override).</p></li><li><p><strong>Every remote host went unreachable at once.</strong> That is the hub, not a per-host fault: peers reach every enrolled box <em>through</em> it now.</p></li></ul><h2 id="Removing-a-box" tabindex="-1">Removing a box <a class="header-anchor" href="#Removing-a-box" aria-label="Permalink to &quot;Removing a box {#Removing-a-box}&quot;">​</a></h2><p>Delete its <code>[host.&lt;host&gt;]</code> block on the hub, <code>sotd topology apply --yes</code> (which disables the listener and removes both generated unit files), and <code>sotd topology sync</code> elsewhere. Nothing needs doing on the box itself — the hub was the only side holding a route.</p>`,16)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
